#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        return 0;
    }

    char *input = argv[1];
    size_t len = strlen(input);

    // Check if input is too long (> 1024 characters)
    if (len > 0x400) {
        puts("TOO_LONG");
        return 0;
    }

    // Normalize the string: convert to lowercase and keep only alphanumeric
    char normalized[1025];
    size_t norm_len = 0;

    for (size_t i = 0; i < len; i++) {
        char c = input[i];

        // Check if character is alphanumeric
        int is_alnum = 0;
        if ((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')) {
            is_alnum = 1;
        } else if (c >= 'A' && c <= 'Z') {
            is_alnum = 1;
            c = c + 0x20;  // Convert to lowercase
        }

        if (is_alnum) {
            normalized[norm_len] = c;
            norm_len++;
        }
    }
    normalized[norm_len] = '\0';

    // Check if normalized string is a palindrome
    int is_palindrome = 1;
    size_t left = 0;
    size_t right = norm_len - 1;

    while (left < right) {
        if (normalized[left] != normalized[right]) {
            is_palindrome = 0;
            break;
        }
        left++;
        right--;
    }

    if (is_palindrome) {
        puts("PALINDROME");
    } else {
        puts("NOT_PALINDROME");
    }

    return 0;
}
